#!/usr/bin/env python3
# Generated by nova via A2A Mesh delegation
"""
Mesh Health Digest — heti automatikus önriport
================================================
Collects node metrics (heartbeat latency, task success rate,
PG replication lag, offline-queue depth) and generates a weekly
summary with trend analysis. Deterministic, no LLM required.

Usage:
    python mesh_health_digest.py collect          # Collect metrics now
    python mesh_health_digest.py digest            # Generate weekly digest
    python mesh_health_digest.py digest --json    # JSON output
    python mesh_health_digest.py status            # Show last collection
"""

import argparse
import json
import os
import sqlite3
import statistics
import subprocess
import sys
import time
from dataclasses import dataclass, asdict, field
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Optional

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parent
DATA_DIR = REPO_ROOT / "data" / "health_digest"
DB_PATH = DATA_DIR / "health_digest.db"
CONFIG_PATH = REPO_ROOT / "config" / "mesh_nodes.yaml"

# Ensure data directory exists
DATA_DIR.mkdir(parents=True, exist_ok=True)

# ---------------------------------------------------------------------------
# Data models
# ---------------------------------------------------------------------------

@dataclass
class NodeMetrics:
    node_id: str
    timestamp: str  # ISO 8601
    heartbeat_latency_ms: float
    task_success_rate: float  # 0.0 - 1.0
    pg_replication_lag_mb: float
    offline_queue_depth: int
    status: str  # "online" | "degraded" | "offline"
    error: Optional[str] = None

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass
class TrendPoint:
    metric_name: str
    current: float
    previous: float
    delta: float
    delta_pct: float
    direction: str  # "up" | "down" | "stable"

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass
class NodeDigest:
    node_id: str
    current_status: str
    metrics: dict
    trends: list  # list of TrendPoint dicts
    health_score: float  # 0-100
    flags: list  # list of warning strings

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass
class WeeklyDigest:
    generated_at: str
    period_start: str
    period_end: str
    nodes: list  # list of NodeDigest dicts
    summary: dict
    recommendations: list

    def to_dict(self) -> dict:
        return asdict(self)


# ---------------------------------------------------------------------------
# Database layer
# ---------------------------------------------------------------------------

def get_db() -> sqlite3.Connection:
    conn = sqlite3.connect(str(DB_PATH))
    conn.row_factory = sqlite3.Row
    conn.execute("""
        CREATE TABLE IF NOT EXISTS metrics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            node_id TEXT NOT NULL,
            timestamp TEXT NOT NULL,
            heartbeat_latency_ms REAL,
            task_success_rate REAL,
            pg_replication_lag_mb REAL,
            offline_queue_depth INTEGER,
            status TEXT,
            error TEXT
        )
    """)
    conn.execute("""
        CREATE INDEX IF NOT EXISTS idx_metrics_node_ts
        ON metrics(node_id, timestamp)
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS digests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            generated_at TEXT NOT NULL,
            period_start TEXT NOT NULL,
            period_end TEXT NOT NULL,
            content_json TEXT NOT NULL
        )
    """)
    conn.commit()
    return conn


def save_metrics(conn: sqlite3.Connection, metrics: NodeMetrics) -> None:
    conn.execute("""
        INSERT INTO metrics
            (node_id, timestamp, heartbeat_latency_ms, task_success_rate,
             pg_replication_lag_mb, offline_queue_depth, status, error)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        metrics.node_id,
        metrics.timestamp,
        metrics.heartbeat_latency_ms,
        metrics.task_success_rate,
        metrics.pg_replication_lag_mb,
        metrics.offline_queue_depth,
        metrics.status,
        metrics.error,
    ))
    conn.commit()


def get_latest_metrics(conn: sqlite3.Connection, node_id: str) -> Optional[dict]:
    row = conn.execute("""
        SELECT * FROM metrics WHERE node_id = ?
        ORDER BY timestamp DESC LIMIT 1
    """, (node_id,)).fetchone()
    return dict(row) if row else None


def get_previous_metrics(conn: sqlite3.Connection, node_id: str,
                         before_ts: str) -> Optional[dict]:
    row = conn.execute("""
        SELECT * FROM metrics WHERE node_id = ? AND timestamp < ?
        ORDER BY timestamp DESC LIMIT 1
    """, (node_id, before_ts)).fetchone()
    return dict(row) if row else None


def get_metrics_in_range(conn: sqlite3.Connection, node_id: str,
                         start_ts: str, end_ts: str) -> list:
    rows = conn.execute("""
        SELECT * FROM metrics WHERE node_id = ? AND timestamp >= ? AND timestamp <= ?
        ORDER BY timestamp ASC
    """, (node_id, start_ts, end_ts)).fetchall()
    return [dict(r) for r in rows]


def get_all_node_ids(conn: sqlite3.Connection) -> list:
    rows = conn.execute("SELECT DISTINCT node_id FROM metrics").fetchall()
    return [r["node_id"] for r in rows]


def save_digest(conn: sqlite3.Connection, digest: WeeklyDigest) -> None:
    conn.execute("""
        INSERT INTO digests (generated_at, period_start, period_end, content_json)
        VALUES (?, ?, ?, ?)
    """, (
        digest.generated_at,
        digest.period_start,
        digest.period_end,
        json.dumps(digest.to_dict(), ensure_ascii=False, indent=2),
    ))
    conn.commit()


# ---------------------------------------------------------------------------
# Node discovery
# ---------------------------------------------------------------------------

def discover_nodes() -> list:
    """Discover mesh nodes from config or running processes."""
    nodes = []

    # Try YAML config first
    if CONFIG_PATH.exists():
        try:
            import yaml
            with open(CONFIG_PATH, "r") as f:
                cfg = yaml.safe_load(f)
            if cfg and "nodes" in cfg:
                for n in cfg["nodes"]:
                    nodes.append({
                        "node_id": n.get("id", n.get("node_id", "")),
                        "host": n.get("host", "localhost"),
                        "port": n.get("port", 8080),
                    })
        except Exception:
            pass

    # Fallback: scan for mesh processes
    if not nodes:
        nodes = _discover_from_processes()

    # Fallback: use environment variable
    if not nodes:
        env_nodes = os.environ.get("MESH_NODES", "")
        if env_nodes:
            for entry in env_nodes.split(","):
                entry = entry.strip()
                if entry:
                    parts = entry.split(":")
                    nodes.append({
                        "node_id": parts[0],
                        "host": parts[0],
                        "port": int(parts[1]) if len(parts) > 1 else 8080,
                    })

    # Ultimate fallback: self node
    if not nodes:
        nodes = [{"node_id": "self", "host": "localhost", "port": 8080}]

    return nodes


def _discover_from_processes() -> list:
    """Try to find mesh node processes."""
    nodes = []
    try:
        result = subprocess.run(
            ["ps", "aux"],
            capture_output=True, text=True, timeout=5
        )
        for line in result.stdout.splitlines():
            if "a2a_mesh" in line.lower() or "mesh_node" in line.lower():
                # Extract node id if present
                for token in line.split():
                    if token.startswith("--node-id="):
                        nid = token.split("=", 1)[1]
                        nodes.append({"node_id": nid, "host": "localhost", "port": 8080})
                        break
    except Exception:
        pass
    return nodes


# ---------------------------------------------------------------------------
# Metric collectors
# ---------------------------------------------------------------------------

def collect_heartbeat_latency(host: str, port: int) -> tuple:
    """Measure round-trip time to node's heartbeat endpoint."""
    import http.client
    try:
        start = time.monotonic()
        conn = http.client.HTTPConnection(host, port, timeout=5)
        conn.request("GET", "/health")
        resp = conn.getresponse()
        resp.read()
        elapsed = (time.monotonic() - start) * 1000  # ms
        conn.close()
        if resp.status == 200:
            return elapsed, "online", None
        else:
            return elapsed, "degraded", f"HTTP {resp.status}"
    except Exception as e:
        return -1.0, "offline", str(e)


def collect_task_success_rate(node_id: str, host: str, port: int) -> tuple:
    """Query node for task success/failure counts."""
    import http.client
    try:
        conn = http.client.HTTPConnection(host, port, timeout=5)
        conn.request("GET", "/metrics/tasks")
        resp = conn.getresponse()
        body = resp.read().decode("utf-8", errors="replace")
        conn.close()
        if resp.status == 200:
            data = json.loads(body)
            total = data.get("total_tasks", 0)
            succeeded = data.get("succeeded_tasks", 0)
            if total > 0:
                return succeeded / total, None
            return 1.0, None
        return 0.0, f"HTTP {resp.status}"
    except Exception as e:
        return 0.0, str(e)


def collect_pg_replication_lag(node_id: str, host: str, port: int) -> tuple:
    """Query PostgreSQL replication lag (if available)."""
    import http.client
    try:
        conn = http.client.HTTPConnection(host, port, timeout=5)
        conn.request("GET", "/metrics/pg")
        resp = conn.getresponse()
        body = resp.read().decode("utf-8", errors="replace")
        conn.close()
        if resp.status == 200:
            data = json.loads(body)
            return float(data.get("replication_lag_mb", 0.0)), None
        return 0.0, f"HTTP {resp.status}"
    except Exception as e:
        return 0.0, str(e)


def collect_offline_queue_depth(node_id: str, host: str, port: int) -> tuple:
    """Query node's offline queue depth."""
    import http.client
    try:
        conn = http.client.HTTPConnection(host, port, timeout=5)
        conn.request("GET", "/metrics/queue")
        resp = conn.getresponse()
        body = resp.read().decode("utf-8", errors="replace")
        conn.close()
        if resp.status == 200:
            data = json.loads(body)
            return int(data.get("offline_queue_depth", 0)), None
        return 0, f"HTTP {resp.status}"
    except Exception as e:
        return 0, str(e)


def collect_node_metrics(node: dict) -> NodeMetrics:
    """Collect all metrics for a single node."""
    node_id = node["node_id"]
    host = node.get("host", "localhost")
    port = node.get("port", 8080)
    now = datetime.now(timezone.utc).isoformat()

    # Heartbeat
    hb_latency, status, hb_error = collect_heartbeat_latency(host, port)

    # Task success rate
    task_rate, task_error = collect_task_success_rate(node_id, host, port)

    # PG replication lag
    pg_lag, pg_error = collect_pg_replication_lag(node_id, host, port)

    # Offline queue depth
    queue_depth, queue_error = collect_offline_queue_depth(node_id, host, port)

    # Aggregate errors
    errors = [e for e in [hb_error, task_error, pg_error, queue_error] if e and "HTTP 200" not in str(e)]
    error_msg = "; ".join(errors) if errors else None

    # If heartbeat failed, node is offline
    if hb_latency < 0:
        status = "offline"
        task_rate = 0.0
        pg_lag = 0.0
        queue_depth = 0

    return NodeMetrics(
        node_id=node_id,
        timestamp=now,
        heartbeat_latency_ms=round(hb_latency, 2) if hb_latency >= 0 else -1.0,
        task_success_rate=round(task_rate, 4),
        pg_replication_lag_mb=round(pg_lag, 2),
        offline_queue_depth=queue_depth,
        status=status,
        error=error_msg,
    )


# ---------------------------------------------------------------------------
# Trend analysis
# ---------------------------------------------------------------------------

def calculate_trend(metric_name: str, current: float, previous: float) -> TrendPoint:
    delta = current - previous
    if previous != 0:
        delta_pct = (delta / abs(previous)) * 100
    else:
        delta_pct = 0.0 if delta == 0 else float("inf")

    if abs(delta_pct) < 5.0:
        direction = "stable"
    elif delta > 0:
        direction = "up"
    else:
        direction = "down"

    return TrendPoint(
        metric_name=metric_name,
        current=round(current, 4),
        previous=round(previous, 4),
        delta=round(delta, 4),
        delta_pct=round(delta_pct, 2),
        direction=direction,
    )


def calculate_health_score(metrics: dict, trends: list) -> float:
    """Calculate a 0-100 health score for a node."""
    score = 100.0

    # Heartbeat latency penalty
    hb = metrics.get("heartbeat_latency_ms", 0)
    if hb < 0:
        score -= 50  # offline
    elif hb > 500:
        score -= 20
    elif hb > 200:
        score -= 10
    elif hb > 100:
        score -= 5

    # Task success rate penalty
    tsr = metrics.get("task_success_rate", 1.0)
    if tsr < 0.95:
        score -= (1.0 - tsr) * 40

    # PG replication lag penalty
    pg = metrics.get("pg_replication_lag_mb", 0)
    if pg > 100:
        score -= 15
    elif pg > 50:
        score -= 8
    elif pg > 10:
        score -= 3

    # Offline queue depth penalty
    qd = metrics.get("offline_queue_depth", 0)
    if qd > 100:
        score -= 15
    elif qd > 50:
        score -= 8
    elif qd > 10:
        score -= 3

    # Trend penalties (degrading)
    for t in trends:
        if t["metric_name"] == "heartbeat_latency_ms" and t["direction"] == "up":
            score -= min(t["delta_pct"] * 0.1, 10)
        if t["metric_name"] == "task_success_rate" and t["direction"] == "down":
            score -= min(abs(t["delta_pct"]) * 0.1, 10)
        if t["metric_name"] == "pg_replication_lag_mb" and t["direction"] == "up":
            score -= min(t["delta_pct"] * 0.05, 5)
        if t["metric_name"] == "offline_queue_depth" and t["direction"] == "up":
            score -= min(t["delta_pct"] * 0.05, 5)

    return max(0.0, min(100.0, round(score, 1)))


def generate_flags(metrics: dict, trends: list) -> list:
    """Generate warning flags for a node."""
    flags = []

    hb = metrics.get("heartbeat_latency_ms", 0)
    if hb < 0:
        flags.append("OFFLINE — heartbeat unreachable")
    elif hb > 500:
        flags.append(f"CRITICAL heartbeat latency: {hb}ms")
    elif hb > 200:
        flags.append(f"WARN heartbeat latency: {hb}ms")

    tsr = metrics.get("task_success_rate", 1.0)
    if tsr < 0.80:
        flags.append(f"CRITICAL task success rate: {tsr:.1%}")
    elif tsr < 0.95:
        flags.append(f"WARN task success rate: {tsr:.1%}")

    pg = metrics.get("pg_replication_lag_mb", 0)
    if pg > 100:
        flags.append(f"CRITICAL PG replication lag: {pg}MB")
    elif pg > 50:
        flags.append(f"WARN PG replication lag: {pg}MB")

    qd = metrics.get("offline_queue_depth", 0)
    if qd > 100:
        flags.append(f"CRITICAL offline queue depth: {qd}")
    elif qd > 50:
        flags.append(f"WARN offline queue depth: {qd}")

    # Trend-based flags
    for t in trends:
        if t["direction"] == "up" and t["delta_pct"] > 50:
            if t["metric_name"] in ("heartbeat_latency_ms", "pg_replication_lag_mb",
                                     "offline_queue_depth"):
                flags.append(f"TREND {t['metric_name']} rising +{t['delta_pct']:.0f}%")
        if t["direction"] == "down" and t["delta_pct"] < -10:
            if t["metric_name"] == "task_success_rate":
                flags.append(f"TREND task success rate dropping {t['delta_pct']:.0f}%")

    return flags


# ---------------------------------------------------------------------------
# Digest generation
# ---------------------------------------------------------------------------

def generate_weekly_digest(conn: sqlite3.Connection,
                           output_json: bool = False) -> str:
    """Generate the weekly digest report."""
    now = datetime.now(timezone.utc)
    period_end = now.isoformat()
    period_start = (now - timedelta(days=7)).isoformat()

    node_ids = get_all_node_ids(conn)
    if not node_ids:
        msg = "No metrics collected yet. Run 'collect' first."
        if output_json:
            return json.dumps({"error": msg}, ensure_ascii=False)
        return msg

    node_digests = []
    all_flags = []
    all_scores = []

    for node_id in node_ids:
        latest = get_latest_metrics(conn, node_id)
        if not latest:
            continue

        previous = get_previous_metrics(conn, node_id, latest["timestamp"])

        trends = []
        if previous:
            for metric in ["heartbeat_latency_ms", "task_success_rate",
                           "pg_replication_lag_mb", "offline_queue_depth"]:
                cur = latest[metric] if latest[metric] is not None else 0
                prev = previous[metric] if previous[metric] is not None else 0
                if cur < 0:
                    cur = 0
                t = calculate_trend(metric, float(cur), float(prev))
                trends.append(t.to_dict())

        # Weekly averages
        weekly = get_metrics_in_range(conn, node_id, period_start, period_end)
        weekly_avg = {}
        if weekly:
            for metric in ["heartbeat_latency_ms", "task_success_rate",
                           "pg_replication_lag_mb", "offline_queue_depth"]:
                vals = [w[metric] for w in weekly
                        if w[metric] is not None and w[metric] >= 0]
                if vals:
                    weekly_avg[f"avg_{metric}"] = round(statistics.mean(vals), 2)
                    if len(vals) > 1:
                        weekly_avg[f"stdev_{metric}"] = round(statistics.stdev(vals), 2)
                    weekly_avg[f"min_{metric}"] = round(min(vals), 2)
                    weekly_avg[f"max_{metric}"] = round(max(vals), 2)
                else:
                    weekly_avg[f"avg_{metric}"] = None
            weekly_avg["samples"] = len(weekly)

        current_metrics = {
            "heartbeat_latency_ms": latest["heartbeat_latency_ms"],
            "task_success_rate": latest["task_success_rate"],
            "pg_replication_lag_mb": latest["pg_replication_lag_mb"],
            "offline_queue_depth": latest["offline_queue_depth"],
            "status": latest["status"],
            "timestamp": latest["timestamp"],
            "weekly": weekly_avg,
        }

        flags = generate_flags(current_metrics, trends)
        health_score = calculate_health_score(current_metrics, trends)

        all_flags.extend([(node_id, f) for f in flags])
        all_scores.append(health_score)

        nd = NodeDigest(
            node_id=node_id,
            current_status=latest["status"],
            metrics=current_metrics,
            trends=trends,
            health_score=health_score,
            flags=flags,
        )
        node_digests.append(nd.to_dict())

    # Sort by health score ascending (worst first)
    node_digests.sort(key=lambda x: x["health_score"])

    # Summary
    summary = {
        "total_nodes": len(node_digests),
        "online_nodes": sum(1 for n in node_digests if n["current_status"] == "online"),
        "degraded_nodes": sum(1 for n in node_digests if n["current_status"] == "degraded"),
        "offline_nodes": sum(1 for n in node_digests if n["current_status"] == "offline"),
        "avg_health_score": round(statistics.mean(all_scores), 1) if all_scores else 0,
        "total_flags": len(all_flags),
        "critical_flags": sum(1 for _, f in all_flags if "CRITICAL" in f or "OFFLINE" in f),
        "warning_flags": sum(1 for _, f in all_flags if "WARN" in f),
        "trend_flags": sum(1 for _, f in all_flags if "TREND" in f),
    }

    # Recommendations
    recommendations = []
    for nd in node_digests:
        if nd["health_score"] < 50:
            recommendations.append(
                f"⚠️  {nd['node_id']}: health={nd['health_score']}/100 — "
                f"immediate attention needed. Flags: {'; '.join(nd['flags'])}"
            )
        elif nd["health_score"] < 75:
            recommendations.append(
                f"📋 {nd['node_id']}: health={nd['health_score']}/100 — "
                f"monitor closely. Flags: {'; '.join(nd['flags']) if nd['flags'] else 'none'}"
            )
    if not recommendations:
        recommendations.append("✅ All nodes healthy. No action needed.")

    digest = WeeklyDigest(
        generated_at=now.isoformat(),
        period_start=period_start,
        period_end=period_end,
        nodes=node_digests,
        summary=summary,
        recommendations=recommendations,
    )

    save_digest(conn, digest)

    if output_json:
        return json.dumps(digest.to_dict(), ensure_ascii=False, indent=2)

    return format_digest_text(digest)


def format_digest_text(digest: WeeklyDigest) -> str:
    """Format digest as readable text report."""
    lines = []
    lines.append("=" * 72)
    lines.append("  📊 MESH HEALTH DIGEST — Weekly Summary")
    lines.append("=" * 72)
    lines.append(f"  Period: {digest.period_start[:10]} → {digest.period_end[:10]}")
    lines.append(f"  Generated: {digest.generated_at}")
    lines.append("")

    s = digest.summary
    lines.append(f"  Nodes: {s['total_nodes']} total | "
                 f"🟢 {s['online_nodes']} online | "
                 f"🟡 {s['degraded_nodes']} degraded | "
                 f"🔴 {s['offline_nodes']} offline")
    lines.append(f"  Avg Health Score: {s['avg_health_score']}/100")
    lines.append(f"  Flags: {s['total_flags']} total "
                 f"({s['critical_flags']} critical, "
                 f"{s['warning_flags']} warning, "
                 f"{s['trend_flags']} trend)")
    lines.append("")
    lines.append("-" * 72)
    lines.append("  NODE DETAILS (sorted by health score, worst first)")
    lines.append("-" * 72)

    for nd in digest.nodes:
        emoji = "🔴" if nd["health_score"] < 50 else \
                "🟡" if nd["health_score"] < 75 else "🟢"

        lines.append("")
        lines.append(f"  {emoji} {nd['node_id']}  "
                     f"[{nd['current_status'].upper()}]  "
                     f"Health: {nd['health_score']}/100")

        m = nd["metrics"]
        lines.append(f"     Heartbeat latency:  {m['heartbeat_latency_ms']} ms")
        lines.append(f"     Task success rate:  {m['task_success_rate']:.1%}")
        lines.append(f"     PG replication lag: {m['pg_replication_lag_mb']} MB")
        lines.append(f"     Offline queue:     {m['offline_queue_depth']}")

        # Weekly stats
        wk = m.get("weekly", {})
        if wk.get("samples", 0) > 0:
            lines.append(f"     Weekly samples:     {wk['samples']}")
            if wk.get("avg_heartbeat_latency_ms") is not None:
                lines.append(
                    f"       avg hb: {wk['avg_heartbeat_latency_ms']}ms "
                    f"(min={wk.get('min_heartbeat_latency_ms','?')}, "
                    f"max={wk.get('max_heartbeat_latency_ms','?')})"
                )
            if wk.get("avg_task_success_rate") is not None:
                lines.append(f"       avg task success: {wk['avg_task_success_rate']:.1%}")
            if wk.get("avg_pg_replication_lag_mb") is not None:
                lines.append(f"       avg PG lag: {wk['avg_pg_replication_lag_mb']}MB")
            if wk.get("avg_offline_queue_depth") is not None:
                lines.append(f"       avg queue depth: {wk['avg_offline_queue_depth']}")

        # Trends
        if nd["trends"]:
            lines.append("     Trends (vs previous collection):")
            for t in nd["trends"]:
                arrow = "↑" if t["direction"] == "up" else \
                        "↓" if t["direction"] == "down" else "→"
                lines.append(
                    f"       {t['metric_name']}: {t['previous']} → {t['current']} "
                    f"{arrow} {t['delta_pct']:+.1f}%"
                )

        # Flags
        if nd["flags"]:
            lines.append("     Flags:")
            for f in nd["flags"]:
                lines.append(f"       • {f}")
        else:
            lines.append("     Flags: none")

    lines.append("")
    lines.append("-" * 72)
    lines.append("  RECOMMENDATIONS")
    lines.append("-" * 72)
    for rec in digest.recommendations:
        lines.append(f"  {rec}")

    lines.append("")
    lines.append("=" * 72)
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------

def cmd_collect() -> str:
    """Collect metrics from all discovered nodes."""
    conn = get_db()
    nodes = discover_nodes()
    results = []

    for node in nodes:
        metrics = collect_node_metrics(node)
        save_metrics(conn, metrics)
        results.append(metrics.to_dict())

    conn.close()

    lines = [f"Collected metrics from {len(results)} node(s) at "
             f"{datetime.now(timezone.utc).isoformat()}"]
    for r in results:
        status_emoji = "🟢" if r["status"] == "online" else \
                       "🟡" if r["status"] == "degraded" else "🔴"
        lines.append(f"  {status_emoji} {r['node_id']}: "
                     f"hb={r['heartbeat_latency_ms']}ms, "
                     f"task_success={r['task_success_rate']:.1%}, "
                     f"pg_lag={r['pg_replication_lag_mb']}MB, "
                     f"queue={r['offline_queue_depth']}")
        if r["error"]:
            lines.append(f"     error: {r['error']}")

    return "\n".join(lines)


def cmd_digest(json_output: bool = False) -> str:
    """Generate the weekly digest."""
    conn = get_db()
    result = generate_weekly_digest(conn, output_json=json_output)
    conn.close()
    return result


def cmd_status() -> str:
    """Show last collection status for all nodes."""
    conn = get_db()
    node_ids = get_all_node_ids(conn)
    if not node_ids:
        conn.close()
        return "No metrics collected yet. Run 'python mesh_health_digest.py collect' first."

    lines = ["Last known status of all nodes:"]
    lines.append("-" * 60)
    for nid in node_ids:
        latest = get_latest_metrics(conn, nid)
        if latest:
            emoji = "🟢" if latest["status"] == "online" else \
                    "🟡" if latest["status"] == "degraded" else "🔴"
            lines.append(
                f"  {emoji} {nid} [{latest['status'].upper()}]\n"
                f"     last seen: {latest['timestamp']}\n"
                f"     hb={latest['heartbeat_latency_ms']}ms, "
                f"task={latest['task_success_rate']:.1%}, "
                f"pg={latest['pg_replication_lag_mb']}MB, "
                f"queue={latest['offline_queue_depth']}"
            )
            if latest["error"]:
                lines.append(f"     error: {latest['error']}")
    conn.close()
    return "\n".join(lines)


def cmd_history(node_id: Optional[str] = None, limit: int = 20) -> str:
    """Show metric history."""
    conn = get_db()
    if node_id:
        node_ids = [node_id]
    else:
        node_ids = get_all_node_ids(conn)

    if not node_ids:
        conn.close()
        return "No metrics found."

    lines = ["Metric History:"]
    for nid in node_ids:
        rows = conn.execute("""
            SELECT * FROM metrics WHERE node_id = ?
            ORDER BY timestamp DESC LIMIT ?
        """, (nid, limit)).fetchall()
        lines.append(f"\n  Node: {nid} ({len(rows)} records)")
        lines.append("  " + "-" * 56)
        for r in rows:
            lines.append(
                f"  {r['timestamp'][:19]} | "
                f"hb={r['heartbeat_latency_ms']}ms | "
                f"task={r['task_success_rate']:.1%} | "
                f"pg={r['pg_replication_lag_mb']}MB | "
                f"q={r['offline_queue_depth']} | "
                f"[{r['status']}]"
            )
    conn.close()
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(
        description="Mesh Health Digest — weekly automated self-report"
    )
    subparsers = parser.add_subparsers(dest="command", help="Available commands")

    subparsers.add_parser("collect", help="Collect metrics from all nodes")
    subparsers.add_parser("digest", help="Generate weekly digest report")
    subparsers.add_parser("status", help="Show last known status of all nodes")

    history_parser = subparsers.add_parser("history", help="Show metric history")
    history_parser.add_argument("--node", type=str, default=None,
                                help="Filter by node ID")
    history_parser.add_argument("--limit", type=int, default=20,
                                help="Max records per node")

    args = parser.parse_args()

    if args.command == "collect":
        print(cmd_collect())
    elif args.command == "digest":
        # Check for --json flag
        json_output = "--json" in sys.argv
        print(cmd_digest(json_output=json_output))
    elif args.command == "status":
        print(cmd_status())
    elif args.command == "history":
        print(cmd_history(node_id=args.node, limit=args.limit))
    else:
        parser.print_help()
        sys.exit(1)


if __name__ == "__main__":
    main()